INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19101, 'Jeremiah 51:2', 'Jeremiah', 51, 2, '&nbsp;زۀ به بابل ته غېر مُلکيان ورولېږم چې هغه چاڼ کړى او د هغۀ مُلک تباه کړى. او هغوئ به په هغۀ د هرې خوا نه حمله وکړى کله چې د هغۀ د تباهۍ ورځ راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19102, 'Jeremiah 51:3', 'Jeremiah', 51, 3, '&nbsp;د بابل فوجيان ليندو راښکلو ته مۀ پرېږدئ، او زغرو اچولو ته يې مۀ پرېږدئ. د هغوئ ځوانان درنه بچ نۀ شى، د هغوئ فوجيان په مکمل توګه تباه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19103, 'Jeremiah 51:4', 'Jeremiah', 51, 4, '&nbsp;هغوئ به په بابل کښې مړۀ شى، او د هغۀ په کوڅو کښې به سخت زخميان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19104, 'Jeremiah 51:5', 'Jeremiah', 51, 5, '&nbsp;خو اِسرائيل او يهوداه خُدائ پاک ربُ الافواج نۀ دى هېر کړى، کۀ څۀ هم چې د هغوئ مُلک د بنى اِسرائيلو د مقدس ذات په خلاف د ګناه نه ډک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19105, 'Jeremiah 51:6', 'Jeremiah', 51, 6, '&nbsp;د بابل نه وتښتئ، د خپل ژوند د بچ کولو دپاره منډه ووهئ، د هغۀ د ګناهونو په وجه خپل ځان مۀ مړ کوئ. دا د مالِک خُدائ د انتقام وخت دے، هغه به ورته پوره بدل ورکړى د کوم چې بابل حقدار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19106, 'Jeremiah 51:7', 'Jeremiah', 51, 7, '&nbsp;بابل د مالِک خُدائ په لاس کښې د سرو زرو پياله وه، هغه پيالۍ چې ټوله زمکه يې نشه کړه. قومونو د هغۀ شراب وڅښل نو په دې وجه هغوئ اوس مست شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19107, 'Jeremiah 51:8', 'Jeremiah', 51, 8, '&nbsp;خو ناګهانه بابل هم راوغورزېدو په هغۀ ماتم وکړئ. د هغۀ زخمونو له مرهم ورکړئ. کېدے شى چې هغه شفا ومومى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19108, 'Jeremiah 51:9', 'Jeremiah', 51, 9, '&nbsp;مونږ به هغۀ ته شفا ورکړې وه کۀ چرې مونږ کولے شو، خو هغه اوس نۀ رغيږى. راځئ چې اوس هغه پرېږدو او هر يو خپل مُلک ته واپس لاړ شُو، د هغۀ سزا اوس آسمان ته رسېدلې ده، دا دومره لويه ده چې هغه اوس د اندازه کولو نه بهر ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19109, 'Jeremiah 51:10', 'Jeremiah', 51, 10, '&nbsp;مالِک خُدائ دا خبره څرګنده کړه چې مونږ په حقه يُو. راځئ چې په صيون کښې هغه څۀ ووايو کوم کارونه چې مالِک خُدائ زمونږ خُدائ پاک کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19110, 'Jeremiah 51:11', 'Jeremiah', 51, 11, '&nbsp;خپل غشى تېرۀ کړئ، او خپل ډالونه راوچت کړئ، مالِک خُدائ دا مادى بادشاهان راوچت کړى دى، چې د بابل خلاف پېش قدمى وکړى او هغه تباه کړى. دا د هغۀ انتقام اخستل دى د هغه چا نه چا چې د هغۀ کور پليت کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19111, 'Jeremiah 51:12', 'Jeremiah', 51, 12, '&nbsp;د بابل د دېوالونو خلاف جنډا اوچته کړئ، د ښار محافظان مضبوط کړئ، او چوکيداران ودروئ او د پټ ګزار دپاره تيارے وکړئ، ځکه چې مالِک خُدائ به خپله منصوبه او مقصد پوره کړى، هغۀ چې څۀ وفرمائيل نو هم هغه به د بابل د خلقو سره وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19112, 'Jeremiah 51:13', 'Jeremiah', 51, 13, '&nbsp;اے بابله، تۀ د ډېرو سيندونو په غاړه پروت ښار يې او د مال دولت او تجارت نه ډک يې، خو ستا اَنجام رارسېدلے دے، او ستا د ژوند تار شلېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19113, 'Jeremiah 51:14', 'Jeremiah', 51, 14, '&nbsp;مالِک خُدائ ربُ الافواج په خپل ذات باندې قسم وکړو چې، زۀ به ستاسو ښارونه د دشمنانو نه ډک کړم، لکه څنګه چې يو پټے د مُولخانو نه ډک وى، او هغوئ به په تاسو باندې د فتحې چغې ووهى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19114, 'Jeremiah 51:15', 'Jeremiah', 51, 15, '&nbsp;”مالِک خُدائ په خپل قدرت سره زمکه جوړه کړه. او په خپل حکمت سره يې دُنيا قائمه کړه. او په خپل عقل يې آسمانونه خوارۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19115, 'Jeremiah 51:16', 'Jeremiah', 51, 16, '&nbsp;د هغۀ په حُکم باندې آسمان په غرار شى، هغه وريځې د زمکې د يو سر نه تر بل سره پورې خوروى. هغه برېښنا د باران سره رالېږى او د خپلو ذخيرو نه هوا رالوځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19116, 'Jeremiah 51:17', 'Jeremiah', 51, 17, '&nbsp;د انسان ټول نسلونه بې‌عقله او بې‌علمه دى، هغه کاريګر چې بُتان جوړوى دوئ به د دې بُتانو په وجه وشرميږى، ځکه چې د دوئ بُتان هم دوکه ده او ساه په کښې نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19117, 'Jeremiah 51:18', 'Jeremiah', 51, 18, '&nbsp;دا بُتان فضول او د مسخرو څيزونه دى. کله چې د هغوئ د حساب کِتاب ورځ راشى دا به ټول تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19118, 'Jeremiah 51:19', 'Jeremiah', 51, 19, '&nbsp;خو مالِک خُدائ د يعقوب ميراث د دې بُتانو په شان نۀ دے. هغه د هر شى خالق دے، د بنى اِسرائيلو په شمول چې د هغۀ خپل قوم دے. او د هغۀ نوم ربُ الافواج دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19119, 'Jeremiah 51:20', 'Jeremiah', 51, 20, '&nbsp;مالِک خُدائ فرمائى چې، ”اے بابله، تۀ زما د جنګ تبر يې، او زما د جنګ وسله يې. ستا په ذريعه به زۀ قومونه ذره ذره کوم، او زۀ به په تا بادشاهتونه تباه کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19120, 'Jeremiah 51:21', 'Jeremiah', 51, 21, '&nbsp;زۀ به ستا په ذريعه آسونه او د هغۀ سوارۀ ذره ذره کوم، زۀ به په تا ګاډۍ او د هغې چلوونکى تس نس کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19121, 'Jeremiah 51:22', 'Jeremiah', 51, 22, '&nbsp;زۀ به په تا ښځې او سړى ذره ذره کوم، زۀ به په تا بوډاګان او ځوانان وژنم، زۀ به په تا ځوانان او پېغلې ذره ذره کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19122, 'Jeremiah 51:23', 'Jeremiah', 51, 23, '&nbsp;زۀ به په تا شپونکى او رمې تس نس کوم، زۀ به په تا زميندار او د غوَيانو جوړې ذره ذره کوم، زۀ به په تا حکمرانان او مشران وژنم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19123, 'Jeremiah 51:24', 'Jeremiah', 51, 24, '&nbsp;”ستا د سترګو د وړاندې به زۀ بابليانو او څوک چې په بابل کښې اوسيږى د هغوئ د بدو کارونو په بدله کښې چې يې په صيون کښې کړى دى بدله ورکړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19124, 'Jeremiah 51:25', 'Jeremiah', 51, 25, '&nbsp;مالِک خُدائ فرمائى چې، ”زۀ ستا په خلاف يم، اے تباه کوونکيه غره، تۀ چې ټوله زمکه تباه کوې. زۀ به خپل لاس ستا په خلاف دراوږد کړم، چې د اوچت ځائ نه دې رانسکور کړم، او چې درنه يو سوزېدلے او د ايرو غر جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19125, 'Jeremiah 51:26', 'Jeremiah', 51, 26, '&nbsp;ستا نه به يو کاڼے هم راوچت نۀ کړے شى چې د ګوټ کاڼے شى، او نۀ به درنه يو کاڼے د بنياد دپاره استعمال شى، ځکه تۀ به د تل دپاره په خرابه بدل شې. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19126, 'Jeremiah 51:27', 'Jeremiah', 51, 27, '&nbsp;په هغه مُلک کښې د بابل خلاف جنډا راوچته کړئ، په قومونو کښې بيګل وغږوئ، قومونه د هغۀ په خلاف د جنګ دپاره تيار کړئ، او دغه بادشاهتونه د هغۀ په خلاف راوچت کړئ يعنې، اراراط، مِنى، او اشکناز بادشاهتونه د هغۀ خلاف راوغواړئ. او د هغۀ خلاف جنګى کمانډر مقرر کړئ، او د هغۀ خلاف دومره آسونه راولئ لکه د مُولخانو پرګله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19127, 'Jeremiah 51:28', 'Jeremiah', 51, 28, '&nbsp;قومونه د بابل خِلاف د جنګ دپاره تيار کړئ. د مادى بادشاهان، د هغوئ حکمرانان او د هغوئ ټول مشران، او هغه ټول مُلکونه چې هغوئ ورباندې حکومت کوى راوغواړئ چې د هغوئ خلاف جنګ وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19128, 'Jeremiah 51:29', 'Jeremiah', 51, 29, '&nbsp;زمکه لړزيږى او د دردونو په وجه چورليږى، ځکه چې مالِک خُدائ د بابل په خلاف چې کومه منصوبه تياره کړې ده هغه نۀ بدلېدونکې ده. نو بابل به په خرابه بدل کړے شى او يو کس به هم هلته نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19129, 'Jeremiah 51:30', 'Jeremiah', 51, 30, '&nbsp;د بابل فوجيانو جنګ بس کړو، او په خپلو برجونو کښې بند پاتې شول. د هغوئ زور ختم شو او هغوئ لکه د ښځو په شان بُزدله شول. حمله کوونکو د هغوئ کورونو ته اور واچولو او د هغوئ د ښار دروازې يې ماتې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19130, 'Jeremiah 51:31', 'Jeremiah', 51, 31, '&nbsp;قاصدان د يو بل نه مخکښې کيږى او په منډه دى چې د بابل بادشاه ته دا پېغام ورسوى او په دې يې خبر کړى چې د هغۀ ټول ښار قبضه شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19131, 'Jeremiah 51:32', 'Jeremiah', 51, 32, '&nbsp;دشمن د سيندونو لارې ګودرې د تښتېدلو دپاره بندې کړې دى او په جبو او لوخو يې اور بل کړے دے او د بابل فوجيان يرې راخستى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19132, 'Jeremiah 51:33', 'Jeremiah', 51, 33, '&nbsp;مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، بابل لکه د درمند په شان تيار دے او اوس هغه وخت رارسېدلے دے چې خلق هغه د پښو لاندې کړى هرکله چې د لو وخت شروع شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19133, 'Jeremiah 51:34', 'Jeremiah', 51, 34, '&nbsp;”نبوکدنضر د بابل بادشاه مونږ لواړ تېر کړُو، او هغۀ مونږ سرګردانه او مات کړُو، هغۀ مونږ لکه د تش منګى په شان يوې خوا ته وغورزولو. لکه د ښامار په شان يې تېر کړُو او زمونږ د ښو غوښو نه يې خپله ګېډه ډکه کړه، او نوره يې بيا د خولې نه تُو کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19134, 'Jeremiah 51:35', 'Jeremiah', 51, 35, '&nbsp;خو اوس دې د صيون اوسېدونکى وائى چې، ”مونږ سره چې کوم ظلم زياتے شوے دے هم هغه شان حالات دې په بابل راشى.“ د يروشلم اوسېدونکى دې وائى چې، ”زمونږ چې کومه وينه توئ شوې ده نو د هغې ذمه وارى دې د بابل په غاړه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19135, 'Jeremiah 51:36', 'Jeremiah', 51, 36, '&nbsp;نو په دې وجه مالِک خُدائ داسې فرمائى چې، ”زۀ به ستاسو د حق دفاع وکړم او ستاسو انتقام به واخلم، زۀ به د هغۀ د سيند او چينو اوبۀ اوچې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19136, 'Jeremiah 51:37', 'Jeremiah', 51, 37, '&nbsp;بابل نه به د تباهۍ ډېرے جوړ شى، او ګيدړان به په کښې غارونه جوړ کړى. هغه به نورو ته د يرې او مسخرو شى، او څوک به هم په کښې نۀ اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19137, 'Jeremiah 51:38', 'Jeremiah', 51, 38, '&nbsp;د بابل ټول خلق به لکه د زمرو په شان شور کوى. او هغه به لکه د زمرو د ورکوټو بچو په شان غريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19138, 'Jeremiah 51:39', 'Jeremiah', 51, 39, '&nbsp;خو کله چې هغوئ په مستۍ کښې راشى نو زۀ به هغوئ دپاره مېلمستيا وکړم او هغوئ به ښۀ نشه کړم، نو بيا به هغوئ په چغو سورو او خندا ګانو کښې داسې د ټول عمر دپاره اودۀ کړم چې بيا به کله هم راوچت نۀ شى. دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19139, 'Jeremiah 51:40', 'Jeremiah', 51, 40, '&nbsp;زۀ به هغوئ لکه د ګډورو، چېلو او ګډانو په شان حلالېدو دپاره بوځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19140, 'Jeremiah 51:41', 'Jeremiah', 51, 41, '&nbsp;مالِک خُدائ د بابل په حقله فرمائى چې، ”د بابل هغه لوئ ښار چې ټولې دُنيا به يې صِفت کولو څنګه شکست وخوړو او قبضه شو، د ټولو قومونو دپاره د بابليانو نه څۀ يروونکے منظر جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19141, 'Jeremiah 51:42', 'Jeremiah', 51, 42, '&nbsp;سمندر به په بابل راواوړى او د هغۀ زورَورى چپې به بابل پټ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19142, 'Jeremiah 51:43', 'Jeremiah', 51, 43, '&nbsp;د هغۀ ښارونه به وران او تباه کړى او په اوچه دشته او ميره باندې به بدل شى، هغه به په داسې زمکه باندې بدل شى چې څوک به هم په کښې نۀ اوسيږى، او نۀ به څوک په کښې سفر کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19143, 'Jeremiah 51:44', 'Jeremiah', 51, 44, '&nbsp;زۀ به د بابل معبود بيل بُت ته سزا ورکړم، او څۀ چې يې خوړلى دى هغه به پرې ګنډير کړم. قومونه به نور د هغۀ عبادت نۀ کوى. او د بابل دېوالونه به راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19144, 'Jeremiah 51:45', 'Jeremiah', 51, 45, '&nbsp;اے زما خلقو د هغۀ نه رابهر شئ. د خپل ژوند د بچ کولو دپاره د هغه ځائ نه منډه کړئ. او د مالِک خُدائ د سخت غضب نه وتښتئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19145, 'Jeremiah 51:46', 'Jeremiah', 51, 46, '&nbsp;تاسو چې په دغه مُلک کومې افواه ګانې اورئ نو چې د هغې په وجه نۀ بې‌زړۀ شئ او نۀ ويرېږئ. دا افواه به کال په کال راځى. ظلم او فساد به مُلک کښې راوچت شى او بادشاهان به د يو بل سره جنګونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19146, 'Jeremiah 51:47', 'Jeremiah', 51, 47, '&nbsp;خو په حقيقت کښې هغه وخت راروان دے چې زۀ به د بابليانو بُتانو ته سزا ورکړم، او د هغۀ ټول مُلک به وشرميږى، او د هغوئ قتل شوى کسان به ټول په کښې مړۀ پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19147, 'Jeremiah 51:48', 'Jeremiah', 51, 48, '&nbsp;نو بيا به آسمان او زمکه او هر څۀ چې په کښې دى د بابل په شکست د خوشحالۍ چغې ووهى، ځکه چې د شمال نه به تباه کوونکى فوجيان په هغۀ حمله وکړى، دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19148, 'Jeremiah 51:49', 'Jeremiah', 51, 49, '&nbsp;لکه څنګه چې بابل د بنى اِسرائيلو او د ټولې دُنيا د قتل عام سبب جوړ شوے وو، نو بيا به هغه هم هغه شان قتل کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19149, 'Jeremiah 51:50', 'Jeremiah', 51, 50, '&nbsp;”تاسو څوک چې د مرګ نه راتښتېدلى يئ، ودرېږئ مه، لاړ شئ. تاسو چې څومره هم لرې يئ نو مالِک خُدائ يادوئ. او د خپل کور يروشلم په حقله سوچ کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19150, 'Jeremiah 51:51', 'Jeremiah', 51, 51, '&nbsp;تاسو وايئ چې، ”مونږ په شرمونو وشرمېدو، او زمونږ بې‌عزتى وشوه او شرم مو په مخ راخور شوے دے، ځکه چې غېر مُلکيان د مالِک خُدائ په مقدس ځائ کښې راداخل شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19151, 'Jeremiah 51:52', 'Jeremiah', 51, 52, '&nbsp;مالِک خُدائ فرمائى چې، ”هغه ورځې راروانې دى کله چې به زۀ د بابل بُتانو ته سزا ورکړم نو د هغوئ د زخمونو زبيرګى به ټول مُلک کښې اورېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19152, 'Jeremiah 51:53', 'Jeremiah', 51, 53, '&nbsp;کۀ بابليان آسمان ته هم وخېژى او هلته يوه مضبوطه قلعه جوړه کړى، نو زۀ به هلته هم دشمنان ورولېږم چې هغوئ چور کړى، مالِک خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19153, 'Jeremiah 51:54', 'Jeremiah', 51, 54, '&nbsp;”د ژړا آوازونه د بابل نه راځى، د لوئ تباهۍ آوازونه د بابليانو د زمکې نه اورېدلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19154, 'Jeremiah 51:55', 'Jeremiah', 51, 55, '&nbsp;مالِک خُدائ به بابل تباه کړى، او هغه به د هغوئ د شور نه ډک ښار خاموشه کړى، دشمن به لکه د اوبو د غضبناکو چپو په شان راروان وى او د هغوئ د آوازونو شور به اورېدلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19155, 'Jeremiah 51:56', 'Jeremiah', 51, 56, '&nbsp;تباه کوونکے به د بابل خلاف راشى، د هغوئ جنګى فوجيان به ونيولے شى او د هغوئ ليندې به ماتې کړے شى. ځکه چې مالِک خُدائ د انتقام اخستلو خُدائ پاک دے او هغه به پوره بدله ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19156, 'Jeremiah 51:57', 'Jeremiah', 51, 57, '&nbsp;زۀ به د هغۀ مشران او پوهان نشه کړم، د هغۀ حکمرانان، آفسران، او فوجيان به هم نشه کړم. هغوئ به د تل دپاره اودۀ شى او بيا به نۀ راپاڅى، دا د بادشاه فرمان دے د چا نوم چې مالِک خُدائ ربُ الافواج دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19157, 'Jeremiah 51:58', 'Jeremiah', 51, 58, '&nbsp;مالِک خُدائ ربُ الافواج داسې فرمائى چې، ”د بابل پيړ دېوالونه به هوار کړے شى او د هغۀ اوچتې دروازې به وسوزولے شى، نو خلقو يې خپل ځان ستړے کړو خو هيڅ فائده يې ونۀ کړه، د دې قوم ټول محنت صرف د اور دپاره خشاک دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19158, 'Jeremiah 51:59', 'Jeremiah', 51, 59, '&nbsp;يرمياه نبى دا پېغام د عملى آفسر سراياه د نيرياه زوئ يعنې د محسياه نمسې ته هغه وخت ورکړو کله چې هغه بابل ته د صدقياه د يهوداه بادشاه د حکومت په څلورم کال د هغۀ سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19159, 'Jeremiah 51:60', 'Jeremiah', 51, 60, '&nbsp;يرمياه د هغه ټولو افتونو د تفصيل په حقله چې په بابل باندې راتلونکى وُو په يو طومار کښې وليکل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19160, 'Jeremiah 51:61', 'Jeremiah', 51, 61, '&nbsp;هغۀ سراياه ته وفرمائيل، ”کله چې تۀ بابل ته ورسېږې نو تۀ دا ټول کلام په اوچت آواز سره خلقو ته ولوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19161, 'Jeremiah 51:62', 'Jeremiah', 51, 62, '&nbsp;نو بيا داسې وايه چې، اے مالِکه خُدايه، تا وفرمائيل چې تاسو به دا ځائ تباه کړئ، نو په دې کښې به نۀ انسان او نۀ ځناور اوسيږى، او دا به د تل دپاره وران ويجاړ پروت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19162, 'Jeremiah 51:63', 'Jeremiah', 51, 63, '&nbsp;کله چې تۀ د دې طومار لوستل بند کړې، نو يو کاڼے ورپورې وتړه او د فرات د سيند په مينځ کښې يې وغورزوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19163, 'Jeremiah 51:64', 'Jeremiah', 51, 64, '&nbsp;نو بيا هغوئ ته ووايه چې، دغه شان به بابليان ډوب شى او هيڅکله به بيا راوچت نۀ شى د هغه افت په وجه کوم چې زۀ په دوئ نازلوم. نو د هغۀ خلق به راوغورزيږى.“ د يرمياه خبرې دلته په دې ځائ باندې ختمې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19164, 'Jeremiah 52:1', 'Jeremiah', 52, 1, '&nbsp;صدقياه د يويشتو کالو وو کله چې هغه د يهوداه بادشاه شو، او هغۀ په يروشلم يوولس کاله بادشاهى وکړه. د هغۀ د مور نامه حموطل وه، چې د يرمياه لور وه، چې هغه د لِبناه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19165, 'Jeremiah 52:2', 'Jeremiah', 52, 2, '&nbsp;خو هغۀ د مالِک خُدائ په وړاندې هغه بدکارونه وکړل، کوم چې يهويقيم بادشاه کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19166, 'Jeremiah 52:3', 'Jeremiah', 52, 3, '&nbsp;دا هر څۀ د يروشلم او يهوداه سره د مالِک خُدائ د قهر په وجه وشول، او په آخر کښې هغۀ هغوئ د خپل حضور نه وشړل. خو اوس صدقياه د بابل بادشاه خلاف سرکشى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19167, 'Jeremiah 52:4', 'Jeremiah', 52, 4, '&nbsp;نو د صدقياه بادشاه د حکومت په نهم کال، په لسمه ورځ د لسمې مياشتې نبوکدنضر د بابل بادشاه د خپل ټول فوج سره په يروشلم حمله وکړه. هغوئ ښار محاصره کړو او د دې د دېوالونو نه يې ګېرچاپېره مورچې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19168, 'Jeremiah 52:5', 'Jeremiah', 52, 5, '&nbsp;يروشلم د صدقياه بادشاه د حکومت تر يوولسم کال پورې محاصره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19169, 'Jeremiah 52:6', 'Jeremiah', 52, 6, '&nbsp;د څلورمې مياشتې په نهمه ورځ د صدقياه د حکومت په يوولسم کال، په ښار کښې قحطى ډېره سخته شوه، او آخر يې ټول خوراک بلکل ختم شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19170, 'Jeremiah 52:7', 'Jeremiah', 52, 7, '&nbsp;بيا د ښار د دېوال يوه حِصه راوغورزولے شوه او ټول فوجيان وتښتېدل. خو دا چې بابليانو ښار محاصره کړے وو، نو هغوئ د شپې د تيارې انتظار کولو. نو بيا هغوئ د بادشاه د باغ وروستو دوو دېوالونو په مينځ کښې دروازې نه وتښتېدل او د اُردن وادۍ طرف ته يې مخه وتړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19171, 'Jeremiah 52:8', 'Jeremiah', 52, 8, '&nbsp;خو د بابليانو فوجيانو صدقياه بادشاه پسې راخستې وه او هغه يې د يريحو په مېدانونو کښې ونيولو، د هغۀ سړو هغه پرېښودو او خوارۀ وارۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19172, 'Jeremiah 52:9', 'Jeremiah', 52, 9, '&nbsp;هغوئ هغه د بابل بادشاه ته رِبله ته بوتلو چې د حمات په مُلک کښې وو. د بابل بادشاه بيا د سزا ورکولو خپله فېصله په صدقياه واوروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19173, 'Jeremiah 52:10', 'Jeremiah', 52, 10, '&nbsp;هغوئ د صدقياه په مخامخ د هغۀ زامن او د يهوداه ټول آفسران حلال کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19174, 'Jeremiah 52:11', 'Jeremiah', 52, 11, '&nbsp;نو هغوئ د صدقياه سترګې وويستلې، د پيتلو په زنځيرونو يې وتړلو او بابل ته يې بوتلو چرته چې هغه د خپل مرګ تر وخته پورې هلته پروت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19175, 'Jeremiah 52:12', 'Jeremiah', 52, 12, '&nbsp;د پينځمې مياشتې په لسمه ورځ په نولسم کال د بابل د بادشاه نبوکدنضر، شاهى کمانډر نبوزردان چې د شاهى فوج مشر وو، يروشلم ته راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19176, 'Jeremiah 52:13', 'Jeremiah', 52, 13, '&nbsp;هغۀ د مالِک خُدائ په عبادتګاه، په شاهى محل او د يروشلم په ټولو کورونو اور ولګولو. هر يو خاص عمارت هغۀ وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19177, 'Jeremiah 52:14', 'Jeremiah', 52, 14, '&nbsp;او د بابل ټولو فوجيانو د شاهى کمانډر په مشرۍ کښې د يروشلم د ښار ګېرچاپېره دېوالونه راوغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19178, 'Jeremiah 52:15', 'Jeremiah', 52, 15, '&nbsp;نو بيا نبوزردان د بابل فوجى کمانډر هغه ځينې غريبانان خلق جلاوطن کړل او نور هغه کسان چې په ښار کښې پاتې وُو، او هم نور ماهِر کاريګران، او هغوئ څوک چې د بابل د بادشاه بګوړه شوى وُو هم بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19179, 'Jeremiah 52:16', 'Jeremiah', 52, 16, '&nbsp;خو نبوزردان څۀ غريبانان خلق په مُلک کښې پرېښودل کوم چې بلکل غريبانان وُو ترڅو هغوئ د انګورو په باغونو او پټو کښې کار وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19180, 'Jeremiah 52:17', 'Jeremiah', 52, 17, '&nbsp;بابليانو هغه د زېړو ستنې ماتې کړې، او هغه ګاډۍ او د زېړو تالاب چې نوم يې سمندر وو، کوم چې د مالِک خُدائ په کور کښې وو او هغوئ ټول زېړ د خپل ځان سره بابل ته يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19181, 'Jeremiah 52:18', 'Jeremiah', 52, 18, '&nbsp;هغوئ د خپل ځان سره ټول هغه سامان يوړلو کوم به چې د خُدائ په کور کښې د خِدمت کولو دپاره استعمالېدلو، لکه بېلچې او د ايرو لوښى، د ډيوو سرپوښونه، چمچۍ، د قربانۍ د وينې اوچتولو جامونه، پيالۍ، د خوشبويۍ سوزولو لوښى او د زېړو نور ټول سامان يې لوټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19182, 'Jeremiah 52:19', 'Jeremiah', 52, 19, '&nbsp;نبوزردان د فوج مشر ځان سره هم هغه وړې کاسې، د خوشبو انګيټۍ، کاسې، دېګونه، ډيوټ دانونه، لوښى، کاسې کومې چې چڼکاو نذرانو دپاره استعمالېدلې او نور ټول سامان کوم چې د سوچه سرو او سپينو زرو نه جوړې شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19183, 'Jeremiah 52:20', 'Jeremiah', 52, 20, '&nbsp;هغه زېړ چې کوم په ستنو کښې وُو، د زېړو سمندر او هغه دولس غوَيان چې ورلاندې جوړ شوى وُو، هغه ستنې، کومې چې سليمان بادشاه د مالِک خُدائ د کور دپاره جوړې کړې وې، دومره زيات درانۀ وُو چې وزن کولو نه بهر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19184, 'Jeremiah 52:21', 'Jeremiah', 52, 21, '&nbsp;دواړه ستنې يو شان وې، هره يوه تقريباً نهۀ ګزه اوچته او تقريباً شپږ ګزه ګول وه، د هغوئ مينځ خالى وو خو د هغوئ د دېوال ګېج تقريباً درې اِنچه غټ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19185, 'Jeremiah 52:22', 'Jeremiah', 52, 22, '&nbsp;د هرې يوې ستنې په سر باندې تقريباً درې ګزه اوچت د زېړو تاج وو چې دا ګېرچاپېره د زېړو په زنځيرونو تړلى شوى انارو ښائسته کړے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19186, 'Jeremiah 52:23', 'Jeremiah', 52, 23, '&nbsp;د هرې ستنې نه ګېرچاپېره شپږ نوې انار لګولے شوى وُو چې ټوټل سل انار ورباندې لګولے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19187, 'Jeremiah 52:24', 'Jeremiah', 52, 24, '&nbsp;نبوزردان د فوج مشر د خپل ځان سره د دې نه علاوه، مشر اِمام شراياه، ورپسې اِمام صفنياه او د مالِک خُدائ د کور نور درې خادمان قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19188, 'Jeremiah 52:25', 'Jeremiah', 52, 25, '&nbsp;د ښار نه هغۀ هغه آفسر بوتلو کوم چې د جنګى فوجيانو مشر وو، او اووۀ د بادشاه ذاتى مشيران چې هغوئ لا تر اوسه په ښار کښې وُو، د فوجى مشر منشى چې هغه د فوجيانو د بهرتى کولو ذمه وار وو او شپېتۀ نور اهم سړى يې هم بوتلل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19189, 'Jeremiah 52:26', 'Jeremiah', 52, 26, '&nbsp;نبوزردان هغوئ ټول ځان له کړل او د صوبه حمات په رِبله ښار کښې يې د بابل بادشاه له بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19190, 'Jeremiah 52:27', 'Jeremiah', 52, 27, '&nbsp;او هلته په رِبله کښې د حمات په زمکه د بابل بادشاه ټول ووژل. نو بيا داسې د يهوداه خلق د خپل مُلک نه پردى مُلک ته بوتلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19191, 'Jeremiah 52:28', 'Jeremiah', 52, 28, '&nbsp;د نبوکدنضر د حکومت په اوؤم کال کښې څوک چې جلاوطن کړے شوى وُو د هغوئ شمېر درې زره او درويشت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19192, 'Jeremiah 52:29', 'Jeremiah', 52, 29, '&nbsp;او د نبوکدنضر په اتلسم کال د حکومت په دوران کښې نور اتۀ سوه او دوه دېرش کسان د يروشلم نه قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19193, 'Jeremiah 52:30', 'Jeremiah', 52, 30, '&nbsp;او د نبوکدنضر د حکومت په درويشتم کال هغه نبوزردان راولېږلو او هغۀ نور اووۀ سوه او پينځۀ څلوېښت کسان قېديان بوتلل چې د ټولو شمېر څلور زره او شپږ سوه کسان شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19194, 'Jeremiah 52:31', 'Jeremiah', 52, 31, '&nbsp;د جلاوطنۍ په اووۀ دېرشم کال يهوياکين د يهوداه بادشاه په کوم کال چې اويل‌مرودک د بابل بادشاه شو، نو هغۀ د يهوداه بادشاه په يهوياکين رحم وکړو او هغه يې د قېدخانې نه د دولسمې مياشتې په پينځويشتمه ورځ آزاد کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19195, 'Jeremiah 52:32', 'Jeremiah', 52, 32, '&nbsp;اويل‌مرودک د هغۀ سره ښۀ سلوک وکړو او د هغه نورو بادشاهانو نه يې هم د لوئ عزت ځائ ورکړو کوم چې د هغۀ سره په بابل کښې جلاوطن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19196, 'Jeremiah 52:33', 'Jeremiah', 52, 33, '&nbsp;نو يهوياکين خپلې د قېدخانې جامې يو خوا ته وويستلې او باقى ټول عمر يې د بادشاه په مېز باندې خوړل څښل کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19197, 'Jeremiah 52:34', 'Jeremiah', 52, 34, '&nbsp;هره ورځ د بابل بادشاه يهوياکين ته باقاعده خرچه ورکوله او هغۀ ورته تر مرګه پورې خرچه مقرره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19198, 'Lamentations 1:1', 'Lamentations', 1, 1, '&nbsp;افسوس، افسوس، هغه ښاريه څنګه يواځې پاتې شوه، چې په يو وخت کښې هغه د خلقو نه ډکه وه. هغه څنګه لکه د يوې کونډې په شان شوه، هغه چې په يو وخت کښې په قومونو کښې ډېره لويه وه. د نورو ښارونو په نسبت هغه لکه د شهزادګۍ وه خو اوس هغه غريبه غلامه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19199, 'Lamentations 1:2', 'Lamentations', 1, 2, '&nbsp;هغه ټوله شپه په سلګو او ژړا تېروى، او په مخ يې د اوښکو سېلابونه بهيږى. په ټولو عاشقانو کښې يې يو هم پاتې نۀ وو، چې ورله تسلى ورکړى. د هغې ټولو دوستانو د هغې سره بې‌وفائى کړې ده، او د هغې دشمنان جوړ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19200, 'Lamentations 1:3', 'Lamentations', 1, 3, '&nbsp;يهوداه جلاوطن کړے شو، د ډېرو سختو مشقتونو سره هغه د نورو مُلکونو په مينځ کښې اوسيږى، او د اوسېدو دپاره هغه د آرام ځائ نۀ لرى. د هغۀ دشمنانو هغه راګېر کړو، او هغۀ ته د تښتېدو موقع نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');